            if x < 0 or x >= n:
                continue
            if y < 0 or y >= len(grid[x]):
                continue
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            stack.append((x-1, y))
            stack.append((x+1, y))
            stack.append((x, y-1))
            stack.append((x, y+1))
    islands = 0
    for i in range(n):
        row_len = len(grid[i])
        for j in range(row_len):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

