def solve(s):
    """Check if brackets are balanced.
    Supports (), [], {}. Ignores other characters. Non‑string input returns False.
    """
    if not isinstance(s, str):
        return False
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

